//! Synthetic install layouts for tests. Everything here is generated by our
//! own code; no game data is involved.

#![allow(dead_code)]

use std::fs;
use std::path::{Path, PathBuf};

/// Kind word used by the synthetic archives for a given file name.
fn kind_word(name: &str) -> (u32, u32) {
    let n = name.to_ascii_lowercase();
    let stem = n
        .trim_start_matches("client_")
        .trim_end_matches(".datx")
        .trim_end_matches(".dat");
    let base = stem.split("_aux_").next().unwrap_or(stem);
    if let Some(r) = base.strip_prefix("cell_") {
        return (0x0203_0000, r.parse().unwrap_or(0));
    }
    if let Some(r) = base.strip_prefix("map_") {
        return (0x020A_0000, r.parse().unwrap_or(0));
    }
    if base.starts_with("local_") {
        return (0x0303_0000, 2);
    }
    let w = match base {
        "general" => 0x0103_0000,
        "gamelogic" => 0x0101_0000,
        "mesh" => 0x0102_0000,
        "anim" => 0x0104_0000,
        "sound" => 0x0107_0000,
        "highres" => 0x0108_0000,
        "surface" => 0x0109_0000,
        _ => 0x0100_0000,
    };
    (w, 0)
}

/// Write a synthetic archive: a header image followed by zeros, `size` bytes.
pub fn write_archive(dir: &Path, name: &str, size: u32) -> PathBuf {
    let (kw, code) = kind_word(name);
    let mut b = vec![0u8; size as usize];
    b[0x100..0x104].copy_from_slice(&[0, 0x50, 0x4C, 0]);
    b[0x140..0x144].copy_from_slice(&0x5442u32.to_le_bytes());
    b[0x144..0x148].copy_from_slice(&256u32.to_le_bytes());
    b[0x148..0x14C].copy_from_slice(&size.to_le_bytes());
    b[0x14C..0x150].copy_from_slice(&kw.to_le_bytes());
    b[0x150..0x154].copy_from_slice(&code.to_le_bytes());
    b[0x174..0x178].copy_from_slice(&112u32.to_le_bytes());
    let f178: u32 = if kw >> 24 == 2 { 0 } else { 3 };
    b[0x178..0x17C].copy_from_slice(&f178.to_le_bytes());
    b[0x17C..0x18C].copy_from_slice(&[0x5A; 16]);
    b[0x18C..0x190].copy_from_slice(&1100u32.to_le_bytes());
    let p = dir.join(name);
    fs::write(&p, b).unwrap();
    p
}

/// The archives of a complete synthetic install.
pub const FULL_SET: &[&str] = &[
    "client_general.dat",
    "client_gamelogic.dat",
    "client_local_English.dat",
    "client_anim.dat",
    "client_mesh.dat",
    "client_mesh_aux_1.datx",
    "client_sound.dat",
    "client_surface.dat",
    "client_surface_aux_1.datx",
    "client_surface_aux_2.datx",
    "client_highres.dat",
    "client_cell_1.dat",
    "client_map_1.dat",
];

/// Create a synthetic install in `dir` with the given archive names, a
/// launcher config and a 64-bit client stub.
pub fn make_install(dir: &Path, archives: &[&str]) {
    fs::create_dir_all(dir).unwrap();
    for a in archives {
        write_archive(dir, a, 2048);
    }
    fs::write(
        dir.join("lotro.launcherconfig"),
        b"\xEF\xBB\xBF<configuration/>",
    )
    .unwrap();
    fs::create_dir_all(dir.join("x64")).unwrap();
    fs::write(dir.join("x64/lotroclient64.exe"), b"MZ stub").unwrap();
    fs::write(dir.join("ProjectVersion"), b"120").unwrap();
}

/// A fake `libraryfolders.vdf` listing `libs` (path, lists the app?).
pub fn library_folders_vdf(libs: &[(&Path, bool)]) -> String {
    let mut s = String::from("\"libraryfolders\"\n{\n");
    for (i, (p, lists)) in libs.iter().enumerate() {
        let path = p.display().to_string().replace('\\', "\\\\");
        s.push_str(&format!(
            "\t\"{i}\"\n\t{{\n\t\t\"path\"\t\t\"{path}\"\n\t\t\"label\"\t\t\"\"\n\t\t\"apps\"\n\t\t{{\n"
        ));
        s.push_str("\t\t\t\"22320\"\t\t\"123\"\n");
        if *lists {
            s.push_str("\t\t\t\"212500\"\t\t\"0\"\n");
        }
        s.push_str("\t\t}\n\t}\n");
    }
    s.push_str("}\n");
    s
}

/// A fake app manifest.
pub fn app_manifest(installdir: &str, buildid: u64) -> String {
    format!(
        "\"AppState\"\n{{\n\t\"appid\"\t\t\"212500\"\n\t\"StateFlags\"\t\t\"4\"\n\t\"installdir\"\t\t\"{installdir}\"\n\t\"buildid\"\t\t\"{buildid}\"\n\t\"UserConfig\"\n\t{{\n\t\t\"language\"\t\t\"english\"\n\t}}\n}}\n"
    )
}
